package com.banglakeys.app

/**
 * Theme-এর ছবি — সব WebP, base64 করে code-এর ভেতরেই রাখা (আলাদা drawable/asset file লাগে না)।
 * মোট প্রায় ৩৬ KB। এই file generate করা — হাতে বদলানোর দরকার নেই।
 */
internal object ThemeAssets {
    private const val TEAL_BG = ""
    private const val MANGA_BG = ""
    private const val INK_EYE_BG = ""
    private const val MANGA_T1 = ""
    private const val MANGA_T2 = ""
    private const val MANGA_T3 = ""
    private const val MANGA_T4 = ""
    private const val MANGA_T5 = ""
    private const val MANGA_T6 = ""
    private const val MANGA_T7 = ""
    private const val MANGA_T8 = ""

    private val map: Map<String, String> = mapOf(
        "teal_bg" to TEAL_BG,
        "manga_bg" to MANGA_BG,
        "ink_eye_bg" to INK_EYE_BG,
        "manga_t1" to MANGA_T1,
        "manga_t2" to MANGA_T2,
        "manga_t3" to MANGA_T3,
        "manga_t4" to MANGA_T4,
        "manga_t5" to MANGA_T5,
        "manga_t6" to MANGA_T6,
        "manga_t7" to MANGA_T7,
        "manga_t8" to MANGA_T8,
    )

    fun get(name: String): String? = map[name]
}
